const items = $input.all();
const out = [];
for (let i = 0; i < items.length; i++) {
  const it = items[i];
  let ok = false;
  let reason = 'unverified';
  try {
    const raw = await this.helpers.getBinaryDataBuffer(i, 'data');
    const sig = (it.json.headers || {})['x-hub-signature-256'] || '';
    const dir = $env.AUTOMATION_DIR || '/home/node/automation';
    const v = require(dir + '/security/verify-webhooks.js');
    const res = v.verifyMetaSignature(raw, sig, $env.META_APP_SECRET);
    ok = !!(res && res.ok === true);
    reason = ok ? 'ok' : String((res && res.reason) || 'bad_signature');
  } catch (e) {
    reason = 'verifier_error: ' + String(e.message).slice(0, 80);
  }
  out.push({ json: { signature_ok: ok, reason: reason, body: it.json.body } });
}
return out;

const NL = String.fromCharCode(10);
const TAB = String.fromCharCode(9);
const items = $input.all();
const raw = { rules: null, corpus: '', hide: '', prompt: '', faq: '', guardrail: '' };
for (let i = 0; i < items.length; i++) {
  const b = items[i].binary && items[i].binary.data;
  if (!b) continue;
  const name = b.fileName || '';
  const txt = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('utf8');
  if (name === 'rules.json') raw.rules = JSON.parse(txt);
  else if (name === 'reply-corpus.md') raw.corpus = txt;
  else if (name === 'hide-words.txt') raw.hide = txt;
  else if (name === 'classifier-prompt.md') raw.prompt = txt;
  else if (name === 'faq.md') raw.faq = txt;
  else if (name === 'guardrail.md') raw.guardrail = txt;
}
if (!raw.rules || !raw.corpus || !raw.prompt) throw new Error('community config files missing: rules, corpus or classifier prompt');
const a = raw.prompt.indexOf('---SYSTEM PROMPT START---');
const z = raw.prompt.indexOf('---SYSTEM PROMPT END---');
const system_prompt = raw.prompt.slice(a + 25, z).trim();
const corpus = {};
let facts = '';
let cur = null;
let inFacts = false;
for (const line of raw.corpus.split(NL)) {
  if (line.indexOf('#### ') === 0) {
    const p = line.slice(5).split('|');
    cur = { id: p[0].trim(), lang: (p[1] || 'en').trim() };
    corpus[cur.id] = corpus[cur.id] || {};
    corpus[cur.id][cur.lang] = corpus[cur.id][cur.lang] || [];
    inFacts = false;
    continue;
  }
  if (line.indexOf('## ') === 0) { cur = null; inFacts = line.indexOf('FAQ topics') >= 0; continue; }
  if (cur && line.indexOf('- ') === 0) corpus[cur.id][cur.lang].push(line.slice(2).trim());
  if (inFacts && line.charAt(0) === '|' && line.indexOf('---') < 0 && line.indexOf('| topic') !== 0) {
    const c = line.split('|').map((s) => s.trim()).filter(Boolean);
    if (c.length >= 2) facts += c[0] + ': ' + c[1] + NL;
  }
}
const sec = {};
let s = null;
for (const line of raw.hide.split(NL)) {
  const l = line.replace(String.fromCharCode(13), '');
  const t = l.trim();
  if (!t || t.charAt(0) === '#') continue;
  if (t.charAt(0) === '[' && t.charAt(t.length - 1) === ']') { s = t.slice(1, -1); sec[s] = []; continue; }
  if (s) sec[s].push(l);
}
const regex = (sec['REGEX'] || []).map((l) => { const p = l.split(TAB); return { name: p[0], flags: p[1], source: p.slice(2).join(TAB) }; });
const hide = { kw_spam: (sec['KEYWORDS-SCAM'] || []).map((x) => x.trim()), kw_comp: (sec['KEYWORDS-COMPETITOR-PLACEHOLDERS'] || []).map((x) => x.trim()), regex: regex, allow: (sec['ALLOW'] || []).map((x) => x.trim().toLowerCase()) };
const cfg = { rules: raw.rules, system_prompt: system_prompt, corpus: corpus, facts: facts, faq: raw.faq, guardrail: raw.guardrail, hide: hide };
return [{ json: { cfg: cfg, payload: $('Verify signature').first().json.body } }];

const src = $input.first().json;
let p = src.payload || {};
if (p.body && !p.entry && p.body.entry) p = p.body;
const crypto = require('crypto');
const salt = $env.COMMENT_HASH_SALT || '';
const hash = (x) => crypto.createHash('sha256').update(String(x) + salt).digest('hex').slice(0, 32);
const out = [];
for (const entry of (p.entry || [])) {
  for (const ch of (entry.changes || [])) {
    const v = ch.value || {};
    let ev = null;
    if (p.object === 'page' && ch.field === 'feed' && v.item === 'comment' && v.verb === 'add') {
      ev = { platform: 'fb', owner_id: String(entry.id), comment_id: v.comment_id, post_id: v.post_id, parent_id: v.parent_id || v.post_id, text: v.message || '', author_id: v.from && v.from.id, author_name: (v.from && v.from.name) || '', ts: v.created_time };
      ev.is_nested = ev.parent_id !== ev.post_id;
    } else if (p.object === 'instagram' && ch.field === 'comments') {
      ev = { platform: 'ig', owner_id: String(entry.id), comment_id: v.id, post_id: v.media && v.media.id, parent_id: v.parent_id || (v.media && v.media.id), text: v.text || '', author_id: v.from && v.from.id, author_name: '', ts: entry.time };
      ev.is_nested = !!v.parent_id;
    }
    if (!ev || !ev.comment_id || !ev.author_id) continue;
    if (String(ev.author_id) === ev.owner_id) continue;
    const t = Number(ev.ts);
    ev.created_iso = (t ? new Date(t > 1e12 ? t : t * 1000) : new Date()).toISOString();
    ev.author_hash = hash(ev.author_id);
    ev.first_name = ev.author_name ? String(ev.author_name).split(' ')[0] : '';
    out.push({ json: ev });
  }
}
return out;

const ev = $('Normalise events').item.json;
const ctx = $('Context lookup').item.json;
const cfg = $('Load config').first().json.cfg;
const f = $json || {};
let skip = false;
let reason = '';
if (f.error) { skip = true; reason = 'comment_gone_or_unreadable'; }
else if (f.is_hidden === true || f.hidden === true) { skip = true; reason = 'already_hidden'; }
const raw = ev.text || '';
let low = raw.toLowerCase();
for (const a of cfg.hide.allow) { if (a) low = low.split(a).join(' '); }
const rx = (name) => cfg.hide.regex.filter((r) => r.name.indexOf(name) === 0).map((r) => { try { return new RegExp(r.source, r.flags === '-' ? '' : r.flags); } catch (e) { return null; } }).filter(Boolean);
const emailRx = rx('own_data.email');
let noEmail = low;
for (const e of emailRx) noEmail = noEmail.replace(new RegExp(e.source, 'gi'), ' ');
const own = rx('own_data.').some((r) => r.test(low));
const spamRx = rx('spam.').some((r) => r.test(noEmail) || (r.flags.indexOf('i') < 0 && r.test(raw)));
const kw = (list) => list.some((k) => k && k.charAt(0) !== '<' && low.indexOf(k.trim().toLowerCase()) >= 0);
const spamKw = kw(cfg.hide.kw_spam);
const compHit = kw(cfg.hide.kw_comp) || rx('competitor.').some((r) => r.test(noEmail));
let pre = '';
if (spamKw || spamRx) pre = 'spam';
else if (compHit) pre = 'competitor';
else if (own) pre = 'own_data_posted';
let red = raw.replace(new RegExp('[0-9]{4,}', 'g'), '[digits]');
for (const e of emailRx) red = red.replace(new RegExp(e.source, 'gi'), '[email]');
red = red.slice(0, 600);
const userTurn = { surface: ev.platform + '_comment', text: red, parent_is_ad: !!ctx.ad_id, is_nested_reply: !!ev.is_nested, prior_exchanges_with_person_on_post: ctx.prior_exchanges || 0 };
const classify_body = { model: 'claude-haiku-4-5-20251001', max_tokens: 60, temperature: 0, system: cfg.system_prompt, messages: [ { role: 'user', content: JSON.stringify(userTurn) } ] };
return { json: { skip: skip, skip_reason: reason, precheck_class: pre, own_data_hit: own, text_redacted: red, classify_body: classify_body, ad_id: ctx.ad_id || null, launched_at: ctx.launched_at || null, prior_exchanges: ctx.prior_exchanges || 0, prior_hidden: ctx.prior_hidden || 0, praise_replied: ctx.praise_replied || 0 } };

const pre = $('Pre-checks').item.json;
const r = $json || {};
let cls = null;
try {
  let t = ((r.content && r.content[0] && r.content[0].text) || '').trim();
  t = t.replace(/```json|```/g, '').trim();
  const o = JSON.parse(t);
  const ok = ['question', 'interest', 'objection', 'complaint', 'praise', 'spam', 'abuse', 'competitor', 'off_topic', 'sensitive', 'own_data_posted'];
  if (ok.indexOf(o.intent) >= 0 && typeof o.needs_human === 'boolean' && typeof o.fais_risk === 'boolean' && Object.keys(o).length === 3) cls = { intent: o.intent, needs_human: o.needs_human, fais_risk: o.fais_risk };
} catch (e) { cls = null; }
let sonnet = String(r.model || '').indexOf('sonnet') >= 0;
try { if ($('Classify (Sonnet)').isExecuted) sonnet = true; } catch (e) {}
return { json: Object.assign({}, pre, { classification: cls, invalid: !cls, sonnet_tried: sonnet }) };

const j = $json;
const cfg = $('Load config').first().json.cfg;
const ev = $('Normalise events').item.json;
const rules = cfg.rules;
const G = rules.global;
const AP = String.fromCharCode(39);
const failClosed = !j.classification && !j.precheck_class;
const cls = j.classification || (j.precheck_class ? { intent: j.precheck_class, needs_human: false, fais_risk: false } : { intent: 'off_topic', needs_human: true, fais_risk: true });
let key = cls.intent;
if (cls.fais_risk && ['question', 'objection', 'interest'].indexOf(key) >= 0) key = 'advice_question';
const rule = rules.cases[key] || rules.cases.off_topic;
const nh = cls.needs_human === true;
const humanKeys = ['complaint', 'sensitive'];
const toks = (ev.text || '').toLowerCase().split('').map((c) => ((c >= 'a' && c <= 'z') || c === AP ? c : ' ')).join('').split(' ').filter(Boolean);
const afw = ['ek', 'jy', 'nie', 'dit', 'die', 'wat', 'kos', 'asseblief', 'dankie', 'hoe', 'lank', 'baie', 'vertrou', 'skelm', 'gesprek', 'bel', 'maand', 'wie', 'eintlik', 'vra', 'nog', 'het', 'sal', 'vir', 'maar', 'net', 'vraag', AP + 'n'];
const lang = toks.filter((t) => afw.indexOf(t) >= 0).length >= 2 ? 'af' : 'en';
const pick = (id, lg) => { const v = (cfg.corpus[id] && (cfg.corpus[id][lg] || cfg.corpus[id].en)) || []; if (!v.length) return ''; let s = 0; for (const ch of String(ev.comment_id)) s += ch.charCodeAt(0); return v[s % v.length]; };
const nameFill = (s) => { const n = ev.first_name; if (n) return s.split('{first_name}').join(n); const o = s.split(', {first_name}').join('').split(' {first_name}').join('').split('{first_name}, ').join('').split('{first_name}').join(''); return o.charAt(0).toUpperCase() + o.slice(1); };
const ref = 'cmt_' + (j.ad_id || ('org_' + ev.post_id));
const base = $env.CTWA_BASE_URL;
const link = base ? (base + '/' + ref) : ('https://sortmycover.co.za/?utm_source=meta&utm_medium=comment&utm_campaign=' + ref);
const sast = new Date(Date.now() + 7200000);
const mins = sast.getUTCHours() * 60 + sast.getUTCMinutes();
const inHours = mins >= 420 && mins < 1320;
const due = new Date(Date.UTC(sast.getUTCFullYear(), sast.getUTCMonth(), sast.getUTCDate() + (mins >= 1320 ? 1 : 0), 7, 15) - 7200000).toISOString();
const newAd = !!(j.launched_at && (Date.now() - new Date(j.launched_at).getTime()) < G.new_ad_watch.duration_seconds * 1000);
const sla = newAd ? G.new_ad_watch.public_sla_seconds : (rule.public_sla_seconds || null);
let pubText = '';
let needDraft = false;
const exch = j.prior_exchanges || 0;
const canPublic = !!rule.public_reply && !ev.is_nested && !(nh && humanKeys.indexOf(key) < 0) && !failClosed;
if (canPublic) {
  if (exch >= G.max_public_exchanges_per_person_per_post) {
    if (exch === G.max_public_exchanges_per_person_per_post && ['question', 'interest', 'objection', 'advice_question'].indexOf(key) >= 0) pubText = nameFill(pick('continue_privately', lang));
  } else if (key === 'praise' && ((j.praise_replied || 0) > 0 || exch > 0)) {
    pubText = '';
  } else {
    pubText = nameFill(pick(rule.public_template, lang));
    if (rule.public_draft_from_faq) needDraft = true;
  }
}
let privText = '';
const privOk = rule.private_reply === true && !(nh && humanKeys.indexOf(key) < 0 && key !== 'own_data_posted') && !failClosed;
if (privOk) {
  const disc = nameFill(pick('disclosure_line', lang));
  privText = pick(rule.private_template, lang).split('{disclosure}').join(disc).split('{ctwa_link}').join(link).split('{page_link}').join(link);
  privText = nameFill(privText);
}
const hide = rule.hide === true;
const block = hide && ['spam', 'competitor', 'abuse'].indexOf(key) >= 0 && (j.prior_hidden || 0) >= 2 && ev.platform === 'fb';
const like = rule.like === true && ev.platform === 'fb' && !ev.is_nested && !(nh && humanKeys.indexOf(key) < 0);
let esc = null;
if (failClosed) esc = { kind: 'classifier_invalid', to: ['Jonathan', 'KG'], human_within_seconds: 1800 };
else if (rule.escalation && rule.escalation.to && rule.escalation.kind !== 'hostile_thread') esc = { kind: rule.escalation.kind, to: rule.escalation.to, human_within_seconds: rule.escalation.human_within_seconds };
else if (nh) esc = { kind: 'needs_human', to: ['Jonathan', 'KG'], human_within_seconds: 1800 };
const plan = { platform: ev.platform, owner_id: ev.owner_id, comment_id: ev.comment_id, post_id: ev.post_id, author_id: ev.author_id, ad_id: j.ad_id, created_iso: ev.created_iso, first_name: ev.first_name, key: key, intent: cls.intent, needs_human: nh, fais_risk: cls.fais_risk === true, lang: lang, hide: hide, block: block, like: like, public_text: pubText, private_text: privText, esc: esc, in_hours: inHours, due_at: due, queue: false, sla_target: sla, new_ad: newAd, text_redacted: j.text_redacted, guardrail_trip: false, public_done: false, private_done: false, hide_done: false, esc_done: false, like_done: false };
return { json: { plan: plan, need_draft: needDraft, key: key, cls: cls, text_redacted: j.text_redacted } };

const d = $json;
const cfg = $('Load config').first().json.cfg;
const NL = String.fromCharCode(10);
const facts = cfg.faq ? cfg.faq : cfg.facts;
const lang = d.plan.lang === 'af' ? 'Afrikaans' : 'plain South African English';
const sys = 'You write ONE public reply under a Facebook or Instagram post for SortMyCover. SortMyCover connects people with a licensed financial adviser for a 30-minute call. Rules: at most 2 sentences. Reading grade 5 to 7. Language: ' + lang + '. No exclamation marks. No emoji. No links. No numbers except 30. Never mention price, premium, rand amounts, insurers, products, cover amounts, comparisons or recommendations. Speak about the adviser and SortMyCover in the third person. Do not argue. Use only the FACTS below. For a question, answer from the facts and end by offering to send the details privately. For an objection, state the calm facts only. If the facts do not answer it, output exactly NO_ANSWER. Output only the reply text.' + NL + NL + 'FACTS:' + NL + String(facts).slice(0, 6000);
const hint = d.plan.first_name ? 'Start with the first name: ' + d.plan.first_name + '.' : 'No first name available.';
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 120, temperature: 0.2, system: sys, messages: [ { role: 'user', content: hint + NL + 'Type: ' + d.plan.intent + NL + 'Comment: ' + d.text_redacted } ] };
return { json: Object.assign({}, d, { draft_body: body }) };

const d = $('Decide').item.json;
const cfg = $('Load config').first().json.cfg;
const NL = String.fromCharCode(10);
const r = $json || {};
let retried = false;
try { retried = $('Apply gate').item.json.retried === true; } catch (e) { retried = false; }
const draft = ((r.content && r.content[0] && r.content[0].text) || '').trim();
const reasons = [];
if (!draft || draft.indexOf('NO_ANSWER') >= 0) reasons.push('no_answer');
if (draft.indexOf('!') >= 0) reasons.push('exclamation');
const low = draft.toLowerCase();
if (low.indexOf('http') >= 0 || low.indexOf('www.') >= 0 || low.indexOf('.co.za') >= 0 || low.indexOf('.com') >= 0) reasons.push('link');
const digits = draft.replace(new RegExp('[^0-9]', 'g'), '');
if (digits.length > 0 && digits !== '30') reasons.push('digits');
const banned = ['premium', 'price', 'rand', 'insurer', 'policy', 'policies', 'cover amount', 'how much cover', 'compare', 'comparison', 'cheapest', 'best cover', 'you should', 'guarantee', 'financial advice', 'appointment', 'discovery', 'sanlam', 'old mutual', 'liberty', 'momentum', 'outsurance', 'hollard', '1life', 'assupol', 'brightrock', 'tax', 'recommend', 'suits you', 'suitable'];
for (const b of banned) { if (low.indexOf(b) >= 0) reasons.push('banned:' + b); }
const sentences = draft.split('.').join('|').split('?').join('|').split('|').filter((s) => s.trim().length > 1).length;
if (sentences > 2) reasons.push('too_long');
const stub = 'You are the FAIS guardrail gate for public replies by SortMyCover, a South African lead-generation service that is not a financial services provider. A reply FAILS if it mentions or implies any premium, price, rand amount, cover amount, product, insurer, comparison, suitability, tax treatment, recommendation, or uses the phrase you should. A reply PASSES only if it answers about the call or the company in the third person, or defers to the licensed adviser.';
const sys = (cfg.guardrail ? cfg.guardrail : stub) + NL + NL + 'Community gate mode: judge the DRAFT reply below. Output exactly PASS or FAIL and nothing else.';
let userTurn = '';
try {
  const url = require('url');
  const gm = await import(url.pathToFileURL(($env.REPO_DIR || '/home/node/repo') + '/conversation/guardrail.mjs').href);
  userTurn = gm.classifierInput({ draft: draft, question: d.text_redacted || '', lang: d.plan.lang || 'en', surface: 'public' });
} catch (e) { reasons.push('classifier_input_unavailable'); }
const gate_body = { model: 'claude-haiku-4-5-20251001', max_tokens: 10, temperature: 0, system: sys, messages: [ { role: 'user', content: userTurn } ] };
return { json: { draft: draft, lint_ok: reasons.length === 0, reasons: reasons, retried: retried, gate_body: gate_body } };

const d = $('Decide').item.json;
const L = $('Lint draft').item.json;
const r = $json || {};
const gate = String((r.content && r.content[0] && r.content[0].text) || '').trim().toUpperCase();
const pass = L.lint_ok === true && gate.indexOf('PASS') === 0;
const plan = JSON.parse(JSON.stringify(d.plan));
let retry = false;
if (pass) {
  plan.public_text = L.draft;
} else {
  plan.guardrail_trip = L.reasons.indexOf('no_answer') < 0;
  if (d.key === 'objection' && !L.retried && !d.cls.needs_human) retry = true;
}
return { json: Object.assign({}, d, { plan: plan, retry_sonnet: retry, retried: retry }) };

const plan = $json.plan;
const ageDays = (Date.now() - new Date(plan.created_iso).getTime()) / 86400000;
if (ageDays > 7) plan.private_text = '';
const needsSend = !!(plan.public_text || plan.private_text || plan.esc || plan.like);
plan.queue = !plan.in_hours && needsSend;
if (plan.esc) {
  const MAP = { sensitive: 'human_handoff' };
  plan.esc.kind_requested = plan.esc.kind;
  plan.esc.kind_stored = ($env.ESC_REAL_KINDS === 'true') ? plan.esc.kind : (MAP[plan.esc.kind] || plan.esc.kind);
}
return { json: plan };

const p = $('Action ctx').item.json;
const get = (n) => { try { return $(n).isExecuted ? $(n).item.json : null; } catch (e) { return null; } };
const pub = get('Public reply');
const prv = get('Private reply');
const hid = get('Hide call');
const esc = get('Insert escalation');
const ok = (x) => !!(x && !x.error && (x.id || x.success || x.message_id || x.recipient_id));
const errs = [];
if (p.public_text && !p.public_done && !ok(pub)) errs.push('public');
if (p.private_text && !p.private_done && !ok(prv)) errs.push('private');
if (p.hide && !p.hide_done && !ok(hid)) errs.push('hide');
const np = Object.assign({}, p, { public_done: !!(p.public_done || ok(pub)), private_done: !!(p.private_done || ok(prv)), hide_done: !!(p.hide_done || (p.hide && ok(hid))), esc_done: !!(p.esc_done || esc), like_done: true, queue: false });
const sla = Math.round((Date.now() - new Date(p.created_iso).getTime()) / 1000);
return { json: { comment_id: p.comment_id, intent: p.intent, ad_id: p.ad_id || null, public_id: ok(pub) ? (pub.id || null) : null, private_sent: np.private_done, hidden: np.hide_done, sla_seconds: sla, text_redacted: p.text_redacted, status: errs.length ? 'retry' : 'done', errs: errs.join(','), plan: np } };

const out = [];
for (const it of $input.all()) {
  const r = it.json;
  const plan = typeof r.decision === 'string' ? JSON.parse(r.decision) : (r.decision || {});
  if (!plan.comment_id) continue;
  plan.queue = false;
  plan.public_done = !!r.public_reply_id;
  plan.private_done = !!r.private_reply_sent_at;
  plan.hide_done = r.hidden === true;
  const ageDays = (Date.now() - new Date(plan.created_iso).getTime()) / 86400000;
  if (ageDays > 7) plan.private_text = '';
  out.push({ json: plan });
}
return out;

const rows = $input.all().map((i) => i.json);
if (!rows.length) return [];
const sys = 'You summarise public comment sentiment per ad for SortMyCover, a South African service that books calls with licensed advisers. The input is a JSON array of rows with ad_id, class counts and redacted objection comments. Return ONLY a JSON object with the key ads, an array of objects with the keys ad_id, sentiment (positive, neutral or negative), themes (an array of objects with the keys theme and count, objection themes only, short plain phrases) and flag_media_buyer (boolean, true when negative, abuse and complaint comments are 30 percent or more of the total). No prose.';
const body = { model: 'claude-haiku-4-5-20251001', max_tokens: 1200, temperature: 0, system: sys, messages: [ { role: 'user', content: JSON.stringify(rows) } ] };
return [{ json: { body: body } }];

let o = null;
try {
  const r = $json;
  let t = ((r.content && r.content[0] && r.content[0].text) || '').trim();
  t = t.replace(/```json|```/g, '').trim();
  o = JSON.parse(t);
} catch (e) { o = null; }
if (!o || !Array.isArray(o.ads)) return [];
return o.ads.map((a) => {
  const themes = Array.isArray(a.themes) ? a.themes : [];
  const themeAlert = themes.some((t) => Number(t.count) >= 3);
  return { json: { ad_id: String(a.ad_id), sentiment: a.sentiment || 'neutral', themes: themes, flag_media_buyer: a.flag_media_buyer === true, theme_alert: themeAlert } };
});
